diff --git a/installer/Zero3Pilot.iss b/installer/Zero3Pilot.iss
--- a/installer/Zero3Pilot.iss
+++ b/installer/Zero3Pilot.iss
@@ -48,7 +48,7 @@ function CommandExists(const Name: String): Boolean;
 var
   ResultCode: Integer;
 begin
-  Result := Exec(ExpandConstant('{cmd}'), '/C where \"' + Name + '\" >nul 2>nul', '', SW_HIDE,
